import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errs = [];
page.on('pageerror', e => { errs.push('PAGEERROR ' + e.message); console.log('PAGEERROR:', e.message); });
page.on('console', m => { if (m.type() === 'error') { errs.push(m.text()); console.log('CONSOLE:', m.text()); } });

await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(2500);
await page.screenshot({ path: 'screenshots/n1-menu.png' });

await page.locator('#beginBtn').click({ timeout: 5000 });
await page.waitForTimeout(4200);
await page.screenshot({ path: 'screenshots/n2-bedroom.png' });

// walk forward toward the dresser
await page.keyboard.down('w');
await page.waitForTimeout(900);
await page.keyboard.up('w');
await page.waitForTimeout(300);
await page.screenshot({ path: 'screenshots/n3-dresser.png' });

// turn around roughly (drag not available in pointer lock headlessly) -> use keyboard-free look via mouse moves
for (let i = 0; i < 12; i++) { await page.mouse.move(720 + i * 40, 450); }
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/n4-turn.png' });

// open phone
await page.keyboard.press('Tab');
await page.waitForTimeout(700);
await page.screenshot({ path: 'screenshots/n5-phone.png' });
await page.keyboard.press('Tab');
await page.waitForTimeout(400);

console.log('ERRORS', errs.length);
if (errs.length) console.log(errs.join('\n'));
await browser.close();

