import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const PI = Math.PI;

const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errs = [];
page.on('pageerror', e => { errs.push('PAGEERROR ' + e.message); console.log('PAGEERROR:', e.message); });
page.on('console', m => { if (m.type() === 'error') { errs.push(m.text()); console.log('CONSOLE:', m.text()); } });

await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1800);
await page.evaluate(() => document.getElementById('beginBtn').click());
await page.waitForTimeout(2600);

const shot = async (name) => {
  await page.waitForTimeout(420);
  await page.screenshot({ path: `screenshots/${name}.png` });
};
const pose = async (x, z, y, p) => {
  await page.evaluate(([x,z,y,p]) => window.__game.pose(x,z,y,p), [x,z,y,p]);
};
const state = async () => page.evaluate(() => {
  const g = window.__game;
  return {
    phase: g.S.phase, torch: g.S.hasTorch, key: g.S.hasKey, power: g.S.power,
    truth: g.S.truth, copyRevealed: g.S.copyRevealed, copyVisits: g.S.copyVisits,
    doubleStage: g.S.doubleStage, room: g.S.room,
    inv: document.getElementById('invList').textContent,
    obj: document.getElementById('objText').textContent,
    prompt: document.getElementById('prompt').textContent
  };
});

// ---- gameplay, fast-forwarded through the debug hook ----
await page.evaluate(() => { const g = window.__game; g.torch(); g.power(); g.key(); g.truth(); });
await page.waitForTimeout(600);
console.log('STATE after items', JSON.stringify(await state()));

// ---- reveal copy room, enter it ----
await page.evaluate(() => window.__game.reveal());
await page.waitForTimeout(600);
await pose(-0.4, 2.7, Math.PI, -0.02); // hall, facing the new door (south)
await shot('f1-copy-door');

await pose(-0.4, 4.0, Math.PI, -0.03); // inside the copy room, facing the TV/sofa
await page.waitForTimeout(1500);
console.log('STATE copy entry', JSON.stringify(await state()));
await shot('f2-copy-seated');

// look away long enough to make the seated double vanish
await pose(-0.4, 4.0, 0, -0.03);
await page.waitForTimeout(1900);
console.log('STATE looked away', JSON.stringify(await state()));
await shot('f3-copy-empty');

// leave and re-enter -> standing double
await pose(-0.4, 2.7, Math.PI, -0.02);
await page.waitForTimeout(800);
await pose(-0.4, 4.0, Math.PI, -0.03);
await page.waitForTimeout(1700);
console.log('STATE copy re-entry', JSON.stringify(await state()));
await shot('f4-copy-standing');

// ---- mirror + truth ending ----
await pose(-6.4, 0.3, PI/2, -0.05);
await page.waitForTimeout(900);
console.log('STATE at mirror', JSON.stringify(await state()));
await page.keyboard.press('e');
await page.waitForTimeout(6500);
console.log('STATE after mirror', JSON.stringify(await state()));
await shot('f5-truth-ending');

