let running = true;
function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  if (S.started && !S.ended && !S.paused){
    updatePlayer(dt);
    updateTV(dt);
    updateEvents(dt);
    updateInteract();
    updateHeartbeat(dt);
    if (mirrorMesh) mirrorMesh.visible = player.position.distanceTo(new THREE.Vector3(-7.9,1.5,0.55)) < 8.5;
    if (S.tvOn){
