import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const PI = Math.PI;
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errs = [];
page.on('pageerror', e => { errs.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') { errs.push(m.text()); console.log('CONSOLE', m.text()); } });
await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1600);
await page.evaluate(() => document.getElementById('beginBtn').click());
await page.waitForTimeout(2400);
await page.evaluate(() => { const g = window.__game; g.torch(); g.power(); g.key(); g.reveal(); g.double(2); g.pose(-0.4, 4.25, Math.PI, -0.62); });
await page.waitForTimeout(1200);
console.log('prompt', await page.evaluate(() => document.getElementById('prompt').textContent));
await page.screenshot({ path: 'screenshots/f7-replacement-prompt.png' });
await page.keyboard.press('e');
await page.waitForTimeout(1500);
console.log(await page.evaluate(() => ({
  display: document.getElementById('endingScreen').style.display,
  title: document.getElementById('endingTitle').textContent,
  stats: document.getElementById('endingStats').textContent
})));
await page.screenshot({ path: 'screenshots/f8-replacement-ending.png' });
console.log('ERRORS', errs.length);
await browser.close();

